let seed;
let mySize, margin;
let num;
let myGraphic;
let palette;
let str_wei;

let unit_x, unit_y;
let count;
let t;
let mods = [];
let a, b, c;

function setup() {
	a = TAU / TAU;
	b = a + a;
	c = a - a;
	seed = Math.random() * sq(sq(sq(int(TAU))));
	randomSeed(seed);

	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize, WEBGL);

	perspective(TAU / b / b / b / (a + a / b / b), width / height, TAU, TAU * TAU * TAU * TAU * TAU);
	palette = random(colorScheme).colors.concat();
	background(random(bgcolor));
	frameRate(int(TAU * b * b) * b);
	t = rez = c = n = c;
}

function draw() {
	randomSeed(seed);
	background(random(bgcolor));

	push();
	translate(0, 0, -mySize - mySize);
	rotateX(random(TAU));
	rotateY(random(TAU));
	rotateZ(random(TAU));

	rotateX(random([-a, a]) * frameCount / b / b / b / b / b / b / b);
	rotateY(random([-a, a]) * frameCount / b / b / b / b / b / b);
	rotateZ(random([-a, a]) * frameCount / b / b / b / b / b / b / b);

	let cubeSize = mySize / (a + a / b)/b;
	let plus = cubeSize / b ;

	for (let i = -cubeSize / b; i < cubeSize / b + plus; i += plus * a) {
		for (let j = -cubeSize / b; j < cubeSize / b + plus; j += plus * a) {
			for (let k = -cubeSize / b; k < cubeSize / b + plus; k += plus * a) {
				strokeCap(PROJECT);
				n = noise(i * rez + t, j * rez + t, k * rez + t);
				noStroke();
				fill(random(palette));
				// strokeWeight(random(a, b) * TAU);
				push();
				translate(i, j, k);
				rotateX(random(TAU) + TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				rotateY(random(TAU) + TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				rotateZ(random(TAU) + TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				rotateX(random([-a, a]) * frameCount / b / b / b / b);
				rotateY(random([-a, a]) * frameCount / b / b / b / b);
				rotateZ(random([-a, a]) * frameCount / b / b / b / b);
				push();
				translate(c,c,c);
				// plane(random(mySize/100, mySize/200));
				pop();

				let px = plus / random(a, int(TAU)) / b / sin(n);
				let py = plus / random(a, int(TAU)) / b / cos(n);
				let pz = plus / random(a, int(TAU)) / b / tan(n);
				push();
				translate(px, py, pz);
				sphere(random(mySize/50, mySize/20));
				pop();

				stroke(random(palette));

				strokeWeight(random(a, b) * TAU / b);
				// line(0, 0, 0, px, py, pz);

				pop();
			}
		}
	}
	pop();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("genuary-20250110", "png");
	}
}

